// run with: bare lib/node_modules/vault-base/vault-base.test.js
// 2 devices on one vault base, the bee and the audit log as its 2 views, like identity makes them
const fs = require('bare-fs')
const os = require('bare-os')
const path = require('bare-path')
const b4a = require('b4a')
const Corestore = require('corestore')
const { create_automap } = require('automap')
const { create_auditcore } = require('auditcore')
const { create_vault_base } = require('./')

let failed = 0
const tests = [require('automap/automap.test.js'), require('auditcore/auditcore.test.js')] // the modules vault-base uses
module.exports = async () => { for (const test of tests) await test(); await main(); done() }
if (require.main === module) module.exports()

async function main () {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'vault-base-test-'))
  const store_a = new Corestore(path.join(root, 'a'))
  const store_b = new Corestore(path.join(root, 'b'))
  const a = open(store_a)
  await a.bee.ready()
  await a.audit.ready()
  const b = open(store_b, a.bee.key)
  await b.bee.ready()
  await b.audit.ready()
  check('the bee and the audit log have one key, the base', b4a.equals(a.bee.key, a.audit.key) && a.bee.base === a.audit.base)
  let streams = connect(store_a, store_b)
  const local_length = a.bee.base.local.length
  await a.audit.add_writer(b.bee.base.local.key)
  check('add_writer on the audit log does nothing, the writers belong to the base', a.bee.base.local.length === local_length)
  await a.bee.add_writer(b.bee.base.local.key)
  check('one add_writer through the bee makes the device a writer of both views', await wait([a, b], () => b.bee.writable && b.audit.writable))
  // both views written on both devices
  await a.bee.put('from/a', 1)
  await a.audit.append({ type: 'test', data: { who: 'a' } })
  await b.bee.put('from/b', 2)
  await b.audit.append({ type: 'test', data: { who: 'b' } })
  const both = await wait([a, b], async () => a.audit.length === 2 && b.audit.length === 2 && (await a.bee.get('from/b')) !== null && (await b.bee.get('from/a')) !== null)
  check('a put and an audit entry from each device reach the other one', both, `audit a ${a.audit.length} b ${b.audit.length}`)
  check('the bee only has the keys that were put', !(await keys(a.bee)).some(key => !key.startsWith('from/')), (await keys(a.bee)).join())
  check('the puts go to the bee, not into the log', (await a.audit.read()).every(entry => entry.type === 'test'))
  // written while apart, so autobase reorders both views when they meet. like the vault does it, a put and its log
  // entry go in one append, so apply writes the bee length right after the put into the entry (meta.views.bee)
  streams.forEach(stream => stream.destroy())
  for (let n = 0; n < 3; n++) {
    await logged_put(a, 'apart/a' + n, 'a' + n)
    await logged_put(b, 'apart/b' + n, 'b' + n)
  }
  streams = connect(store_a, store_b)
  await wait([a, b], () => a.audit.length === 8 && b.audit.length === 8)
  const log_a = (await a.audit.read()).map(entry => entry.data.who).join()
  const log_b = (await b.audit.read()).map(entry => entry.data.who).join()
  check('after writing apart both devices have the same log in the same order', log_a === log_b && a.audit.length === 8, `a ${log_a} | b ${log_b}`)
  const bee_a = (await keys(a.bee)).join()
  check('and the same bee', bee_a === (await keys(b.bee)).join() && bee_a.split(',').length === 8, bee_a)
  const views_a = (await a.audit.read()).map(entry => entry.meta.views?.bee).join()
  check('every log entry has the bee length in meta.views, the same on both devices after the reorder', views_a === (await b.audit.read()).map(entry => entry.meta.views?.bee).join() && !views_a.split(',').includes(''), views_a)
  let exact = 0
  for (const entry of await b.audit.read()) {
    if (!entry.data.key) continue
    const at = await b.bee.checkout(entry.meta.views.bee).get(entry.data.key)
    const before = await b.bee.checkout(entry.meta.views.bee - 1).get(entry.data.key)
    if (at?.value === entry.data.who && before === null) exact++
  }
  check('the bee at that length has the put of the entry, one length before it doesnt', exact === 6, `${exact} of 6`)
  // reopen
  streams.forEach(stream => stream.destroy())
  await a.bee.close()
  await store_a.close()
  const store_again = new Corestore(path.join(root, 'a'))
  const again = open(store_again)
  await again.bee.ready()
  await again.audit.ready()
  check('after a restart device a has both views back', again.audit.length === 8 && (await again.bee.get('from/b'))?.value === 2)
  await again.bee.close()
  await b.bee.close()
  await store_again.close()
  await store_b.close()
  fs.rmSync(root, { recursive: true, force: true })
}

async function logged_put (device, key, who) {
  const batch = device.bee.batch()
  await batch.put(key, who)
  await device.audit.append({ type: 'test', data: { who, key } }, { with: batch.entries })
}

function open (store, bootstrap) {
  const base = create_vault_base(store.namespace('vault'), bootstrap)
  return { bee: create_automap({ base }), audit: create_auditcore({ base }) }
}

async function keys (bee) {
  const list = []
  for await (const { key } of bee.create_read_stream()) list.push(key)
  return list
}

function connect (store_a, store_b) {
  const stream_a = store_a.replicate(true)
  const stream_b = store_b.replicate(false)
  stream_a.pipe(stream_b).pipe(stream_a)
  return [stream_a, stream_b]
}

// checks done() again on every update of either device, true once its true
function wait (devices, done) {
  return new Promise((resolve, reject) => {
    const check = () => Promise.resolve(done()).then(ok => {
      if (!ok) return
      for (const device of devices) device.bee.base.off('update', check)
      resolve(true)
    }, reject)
    for (const device of devices) device.bee.base.on('update', check)
    check()
  })
}

function check (name, ok, info = '') {
  if (!ok) failed++
  console.log(`${ok ? 'ok' : 'NOT ok'} ${name}${ok || info === '' ? '' : ` (${info})`}`)
}

function done () {
  console.log(failed ? `${failed} NOT ok` : 'all good')
  if (failed) throw new Error('vault-base tests failed')
}
